'use strict';
const E=PartSaver, provider=new LocalVehicleProvider();let state=provider.load(),page='home',filter='all',driving=false,reportYear=+state.asOf.slice(0,4);if(state.clock==='live')state.asOf=E.iso();
const $=s=>document.querySelector(s),num=n=>Number(n).toLocaleString('ko-KR'),money=n=>num(n)+'원',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',car:'m3 12 2-7h14l2 7v7h-3v-3H6v3H3z M3 12h18 M6 13v1 M18 13v1',parts:'M12 3v4m0 10v4M3 12h4m10 0h4 M5.6 5.6l3 3m6.8 6.8 3 3M5.6 18.4l3-3m6.8-6.8 3-3 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',history:'M6 3h12v18H6z M9 8h6M9 12h6M9 16h4',report:'M4 20V4m0 16h17M8 16v-5m5 5V6m5 10V9',oil:'M5 9h12v10H5z M8 9V5h5v4M17 11l4-3v7l-4 2M3 12h2',filter:'M4 5h16v14H4z M8 7v10m4-10v10m4-10v10',disc:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0M12 5v1m7 6h-1m-6 7v-1m-7-6h1',tire:'M19 12a7 10 0 1 1-14 0 7 10 0 0 1 14 0M15 12a3 6 0 1 1-6 0 3 6 0 0 1 6 0',drop:'M12 2s-7 9-7 13a7 7 0 0 0 14 0c0-4-7-13-7-13z',wiper:'M3 15a12 12 0 0 1 18 0l-3 4H6z M12 19l5-9',battery:'M3 7h18v13H3z M7 7V4h3v3m4 0V4h3v3M6 13h4m-2-2v4m7-2h3',arrow:'m9 5 7 7-7 7',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.parts}"/></svg>`;
const carSvg=`<svg class="car" viewBox="0 0 600 220" aria-hidden="true"><defs><linearGradient id="body" x2="0" y2="1"><stop stop-color="#d6e2dd"/><stop offset=".35" stop-color="#81938e"/><stop offset=".7" stop-color="#3b514e"/><stop offset="1" stop-color="#99aaa3"/></linearGradient><linearGradient id="glass"><stop stop-color="#182e31"/><stop offset="1" stop-color="#314744"/></linearGradient></defs><ellipse cx="300" cy="180" rx="248" ry="16" fill="#060e11" opacity=".55"/><path d="M53 132 78 107l91-16 70-54q16-12 42-12h99q37 1 76 65l90 24 20 25-6 31H50z" fill="url(#body)" stroke="#becdc2" stroke-width="2"/><path d="m184 90 65-51h30l-2 51zM288 39h88q31 3 62 51H288z" fill="url(#glass)" stroke="#c6d3c8"/><path d="M290 99v64M445 100l7 56M74 122l454 1" fill="none" stroke="#a5b8ac" opacity=".65"/><path d="M64 130h58m381-7h45" stroke="#e0f9c7" stroke-width="5"/><path d="M80 158h450" stroke="#172a2b" stroke-width="8"/><g fill="#10191f" stroke="#60756d" stroke-width="4"><circle cx="154" cy="164" r="35"/><circle cx="455" cy="164" r="35"/></g><g fill="#81958d" stroke="#bfcec4" stroke-width="2"><circle cx="154" cy="164" r="20"/><circle cx="455" cy="164" r="20"/></g><g fill="#273c3a"><circle cx="154" cy="164" r="8"/><circle cx="455" cy="164" r="8"/></g><path d="M304 105h23M218 105h23" stroke="#d5e3d7" stroke-width="3"/></svg>`;
function persist(){const ok=provider.save(state);if(!ok)toast(provider.warning);return ok}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3300)}
function go(p){if(driving)return;page=p;render()}
function counts(){const a=E.active(state).map(p=>E.status(state,p));return {ok:a.filter(x=>x.level==='ok').length,soon:a.filter(x=>x.level==='soon').length,over:a.filter(x=>x.level==='over').length}}
function remaining(a){return Number.isFinite(a.remainKm)?(a.remainKm<0?`${num(-a.remainKm)} <small>km 초과</small>`:`${num(a.remainKm)} <small>km 남음</small>`):`${Math.abs(a.days)} <small>일 ${a.days<0?'초과':'남음'}</small>`}
function card(p){const a=E.status(state,p);return `<button class="part" data-detail="${p.id}" aria-label="${p.name} 상세"><div class="row">${icon(p.icon)}<span class="pill ${a.level}">${a.label}</span></div><h3>${p.name}</h3><div class="remaining">${remaining(a)}</div><div class="track ${a.level}"><i style="width:${a.progress}%"></i></div><div class="partfooter">${p.kind} 기준 · ${a.nextDate||'기간 미설정'}${a.days<0?' · 기간 초과':''}</div></button>`}
function chart(){const rows=state.mileage.slice(-7),min=Math.min(...rows.map(x=>x.km))-1000,max=Math.max(...rows.map(x=>x.km))+500;const pts=rows.map((x,i)=>`${i*440/Math.max(1,rows.length-1)},${85-(x.km-min)/(max-min)*75}`).join(' ');return `<svg class="chart" viewBox="0 0 440 100" role="img" aria-label="가상 누적 주행거리 추이"><path d="M0 20H440M0 60H440M0 99H440" stroke="#354047" stroke-dasharray="3 5"/><polyline points="${pts}" fill="none" stroke="#bbf376" stroke-width="3"/>${rows.map((x,i)=>`<circle cx="${i*440/Math.max(1,rows.length-1)}" cy="${85-(x.km-min)/(max-min)*75}" r="4" fill="#bbf376"/>`).join('')}</svg><div class="chart-labels">${rows.map(x=>`<span>${x.date.slice(5)}<br>${num(x.km)} km</span>`).join('')}</div>`}
function home(){const c=counts(),budget=E.plan(state).filter(p=>p.kind==='교체').reduce((a,p)=>a+p.cost,0);return `<div class="grid hero-grid"><section class="panel car-panel"><div class="row"><div><div class="eyebrow">MY GARAGE</div><h2>${esc(state.vehicle.model)}</h2><p class="muted">${state.vehicle.year} · ${esc(state.vehicle.power)} · 시연 차량</p></div><span class="badge">가상 차량</span></div>${carSvg}<div class="odo"><small>누적 주행거리</small><div><span class="big">${num(state.vehicle.odometer)}</span><span class="unit">km</span><button class="tinybutton" id="editMileage">변경</button></div></div></section><section class="panel"><div class="row"><h2>내 차 관리 현황</h2><span class="muted">${E.active(state).length}개 항목</span></div><div class="summary"><div><span>정상</span><strong class="mint">${c.ok}<small class="unit">건</small></strong></div><div><span>점검·교체 임박</span><strong class="orange">${c.soon}<small class="unit">건</small></strong></div><div><span>기준 도달·초과</span><strong class="red">${c.over}<small class="unit">건</small></strong></div></div><div class="helpbox">${c.over?'기준에 도달한 항목이 있습니다. 정차 후 확인하세요.':'교체 주기와 점검 시점을 미리 확인하세요.'}<br>상태 점검 항목은 마모 측정이나 교체 확정이 아닙니다.</div></section></div><div class="section-head"><h2>소모품 한눈에 보기</h2><p>거리·기간 중 먼저 도래하는 기준 적용</p></div><div class="grid cards">${E.active(state).map(card).join('')}</div><div class="grid bottom-grid"><section class="panel"><div class="row"><h2>주행거리 추이</h2><small>가상 누적 거리 · km</small></div>${chart()}</section><section class="panel"><div class="row"><h2>앞으로의 정비 예산</h2><button class="tinybutton" data-go="report">리포트 보기 ↗</button></div><div class="big" style="margin-top:15px">${num(budget)}<span class="unit">원</span></div><p class="subtle">3개월 또는 10,000km 내 정기 교체 예산</p><div class="costline"><span>올해 실제 입력 지출 <small>(시연)</small></span><b>${money(E.expense(state,+state.asOf.slice(0,4)).total)}</b></div></section></div>`}
function vehicle(){return `<section class="panel"><h2>차량 프로필</h2><p class="subtle">현재는 수동 입력·가상 데이터만 사용합니다. 제조사 매뉴얼 자동 조회는 미연동입니다.</p><form id="vehicleForm"><div class="formgrid"><label>차량 모델<select name="model">${['그랜저','아반떼','쏘나타','투싼','싼타페','아이오닉 5','아이오닉 6','기타'].map(v=>`<option ${v===state.vehicle.model?'selected':''}>${v}</option>`).join('')}</select></label><label>연식<input name="year" type="number" min="1990" max="2030" value="${state.vehicle.year}" required></label><label>동력 방식<select name="power">${['가솔린','디젤','하이브리드','플러그인 하이브리드','전기','LPG'].map(v=>`<option ${v===state.vehicle.power?'selected':''}>${v}</option>`).join('')}</select></label><label>현재 누적 주행거리 (km)<input name="odometer" type="number" min="0" max="2000000" step="1" value="${state.vehicle.odometer}" required></label><label>알림 거리 기준 (km 이내)<input name="warningKm" type="number" min="0" max="10000" value="${state.warningKm}" required></label><label>알림 기간 기준 (일 이내)<input name="warningDays" type="number" min="0" max="365" value="${state.warningDays}" required></label><label>날짜 기준<select name="clock"><option value="demo" ${state.clock==='demo'?'selected':''}>시뮬레이션 기준일</option><option value="live" ${state.clock==='live'?'selected':''}>오늘 날짜 (한국시간)</option></select></label><label>시뮬레이션 기준일<input type="date" name="asOf" value="${state.asOf}" required></label></div><div class="helpbox">차량·연식 변경 시에도 주기는 자동으로 인증되지 않습니다. 소모품 상세에서 예시 주기를 수정하세요. 전기차에서는 엔진오일·흡기 필터를 제외합니다. 배터리는 구동용 고전압 배터리가 아닌 12V 보조 배터리입니다.</div><p class="error" id="formError"></p><div class="actions"><button type="button" id="exportData">JSON 백업</button><button class="primary">차량 정보 저장</button></div></form></section><section class="panel" style="margin-top:20px"><h2>시연 데이터 관리</h2><p class="subtle">기본 차량과 가상 이력으로 복원합니다. 기존 브라우저 입력은 삭제됩니다.</p><button id="resetData" style="margin-top:15px">시연 데이터 초기화</button></section>`}
function parts(){let items=E.active(state);if(filter!=='all')items=items.filter(p=>E.status(state,p).level===filter);return `<div class="tabs">${[['all','전체'],['soon','임박'],['over','기준 도달·초과'],['ok','정상']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div><div class="grid cards">${items.map(card).join('')}</div>${!items.length?'<div class="empty">해당 상태의 소모품이 없습니다.</div>':''}<div class="helpbox">모든 주기·비용은 시연용 예시입니다. 브레이크·타이어·와이퍼·12V 배터리는 상태 점검 권장이며 실제 교체 여부는 점검 결과로 결정합니다. 타이어 위치 교환의 별도 주기 관리는 이번 시제품에 포함되지 않습니다.</div>`}
function history(){const rows=[...state.records].sort((a,b)=>b.date.localeCompare(a.date)||b.km-a.km);return `<section class="panel"><div class="row"><div><h2>정비 기록장</h2><p class="subtle">교체·점검 기록을 저장하면 다음 관리 시점이 갱신됩니다.</p></div><button class="primary" id="addRecord">+ 정비 기록</button></div><div class="table-wrap"><table><thead><tr><th>정비일</th><th>소모품 / 유형</th><th>주행거리</th><th>기록 당시 예상</th><th>실제 입력 비용</th><th>관리</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.date}</td><td>${esc(state.parts.find(p=>p.id===r.partId)?.name||r.partId)}<br><small>${r.type} · ${esc(r.shop||'업체 미입력')}</small></td><td>${num(r.km)} km</td><td>${money(r.estimate||0)}</td><td>${money(r.cost)}</td><td><button class="tinybutton" data-record="${r.id}">수정</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="empty">아직 저장된 정비 기록이 없습니다.</p>':''}</section>`}
function report(){const x=E.expense(state,reportYear),planned=E.plan(state),fixed=planned.filter(p=>p.kind==='교체').reduce((s,p)=>s+p.cost,0),conditional=planned.filter(p=>p.kind==='점검').reduce((s,p)=>s+p.cost,0),max=Math.max(1,...x.months);return `<div class="row"><p class="muted">예상 예산과 실제 기록을 분리해 확인하세요.</p><label>지출 연도<select id="reportYear">${[...new Set([...state.records.map(r=>+r.date.slice(0,4)),+state.asOf.slice(0,4),reportYear])].sort((a,b)=>b-a).map(y=>`<option ${y===reportYear?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="grid report-kpis"><section class="panel"><small>향후 정기 교체 예상</small><div class="big mint">${num(fixed)}<span class="unit">원</span></div><p class="subtle">3개월 또는 10,000km 내 · 예시 견적</p></section><section class="panel"><small>${reportYear}년 실제 입력 지출</small><div class="big">${num(x.total)}<span class="unit">원</span></div><p class="subtle">정비 기록 합계 · 가상 데이터 포함</p></section><section class="panel"><small>완료 정비의 예상 대비 차이</small><div class="big ${x.total<=x.estimate?'mint':'orange'}">${x.total-x.estimate>0?'+':''}${num(x.total-x.estimate)}<span class="unit">원</span></div><p class="subtle">동일 기록 예상 ${money(x.estimate)} 대비</p></section></div><section class="panel"><h2>월별 실제 지출</h2><div class="bars">${x.months.map((v,i)=>`<div class="bar-col"><small>${v?num(v):''}</small><div class="bar" style="height:${v/max*130}px"></div><span>${i+1}월</span></div>`).join('')}</div></section><section class="panel" style="margin-top:20px"><div class="row"><h2>향후 관리 계획</h2><small>기준일 ${state.asOf}</small></div><div class="table-wrap"><table><thead><tr><th>소모품</th><th>안내 유형</th><th>다음 거리 / 날짜</th><th>예상 교체 비용</th></tr></thead><tbody>${planned.map(p=>{const a=E.status(state,p);return `<tr><td>${p.name}</td><td><span class="pill ${a.level}">${p.kind==='점검'?'상태 점검 우선':a.label}</span></td><td>${a.nextKm===null?'거리 없음':num(a.nextKm)+' km'} / ${a.nextDate||'기간 없음'}</td><td>${money(p.cost)}${p.kind==='점검'?' <small>(교체 시 가정)</small>':''}</td></tr>`}).join('')}</tbody></table></div><p class="subtle">점검 항목의 조건부 교체 비용 합계 ${money(conditional)}는 정기 교체 예산에 포함하지 않습니다. 모든 예산은 부품별 1회 비용의 합이며 반복 교체·인건비 변동을 예측하지 않습니다.</p></section>`}
function render(){const titles={home:'내 차의 다음을 준비하다',vehicle:'차량 정보',parts:'소모품 관리',history:'정비 이력',report:'유지비 리포트'},c=counts();$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><i>◈</i><div>파츠세이버<small>PartSaver</small></div></div><nav class="nav">${[['home','홈 대시보드'],['vehicle','차량 정보'],['parts','소모품 관리'],['history','정비 이력'],['report','유지비 리포트']].map(([id,t])=>`<button data-go="${id}" class="${page===id?'active':''}" ${driving?'disabled':''}>${icon(id==='vehicle'?'car':id)}${t}</button>`).join('')}</nav><div class="sidefoot"><strong>● 로컬 프로토타입</strong><br>Pleos Connect 연동 준비<br>차량 SDK 미연동 · v1.0<br><br>시연 기준일 ${state.asOf}</div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">YOUR CAR, WELL CARED FOR.</div><h1>${driving?'안전한 주행을 위해':titles[page]}</h1></div><div class="topactions"><span class="badge">가상 데이터 · 시뮬레이션</span><button id="driveToggle" class="quiet">${driving?'D 주행 중 → 정차':'P 정차 중 → 주행'}</button></div></header><div class="notice"><span class="dot"></span>실제 차량 측정값 아님 · 주기와 비용은 시연용 예시 · ${state.clock==='demo'?'시뮬레이션':'한국시간'} 기준일 ${state.asOf}</div>${driving?`<div class="drive"><div>${icon('shield')}<h1>주행에 집중하세요</h1><p class="muted">상세 조회와 입력은 정차 후 이용할 수 있습니다.</p><div class="summary"><div><span>정상</span><strong class="mint">${c.ok}</strong></div><div><span>임박</span><strong class="orange">${c.soon}</strong></div><div><span>기준 도달·초과</span><strong class="red">${c.over}</strong></div></div><p class="subtle">주행 상태는 시연용 수동 전환이며 차량 신호와 연결되어 있지 않습니다.</p></div></div>`:({home,vehicle,parts,history,report}[page]())}<footer>PartSaver Prototype · 실제 교체 여부는 해당 차량 제조사 매뉴얼과 정비 전문가의 점검 결과를 우선합니다.</footer></main></div>`;bind()}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>record(null,b.dataset.record));$('#driveToggle').onclick=()=>{driving=!driving;$('#modal').close();render()};if($('#editMileage'))$('#editMileage').onclick=mileage;if($('#addRecord'))$('#addRecord').onclick=()=>record();if($('#reportYear'))$('#reportYear').onchange=e=>{reportYear=+e.target.value;render()};if($('#vehicleForm')){$('#vehicleForm').onsubmit=saveVehicle;$('#exportData').onclick=exportData;$('#resetData').onclick=()=>{if(confirm('입력한 데이터를 지우고 시연 데이터로 초기화할까요?')){state=E.seed();persist();render();toast('시연 데이터를 복원했습니다.')}}}}
function modal(html){if(driving)return;$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
function mileage(){modal(`<div class="row"><h2>가상 주행거리 변경</h2><button data-close aria-label="닫기">×</button></div><p class="subtle">입력 즉시 8종 소모품의 남은 거리를 다시 계산합니다.</p><form id="mileageForm"><div class="formgrid"><label class="full">누적 주행거리 (km)<input id="mileageInput" name="km" type="number" min="0" max="2000000" step="1" value="${state.vehicle.odometer}" required></label></div><p class="error" id="modalError"></p><div class="actions"><button type="button" data-close>취소</button><button class="primary">주행거리 적용</button></div></form>`);$('#mileageForm').onsubmit=e=>{e.preventDefault();const n=+new FormData(e.target).get('km');if(n<state.vehicle.odometer)return $('#modalError').textContent='누적 주행거리는 현재 값보다 작을 수 없습니다.';setMileage(n);persist();$('#modal').close();render();toast('주행거리와 소모품 상태를 갱신했습니다.')}}
function setMileage(n){state.vehicle.odometer=n;let row=state.mileage.find(x=>x.date===state.asOf);if(row)row.km=n;else state.mileage.push({date:state.asOf,km:n});state.mileage.sort((a,b)=>a.date.localeCompare(b.date))}
function detail(id){const p=state.parts.find(p=>p.id===id),a=E.status(state,p);modal(`<div class="row"><h2>${p.name}</h2><button data-close aria-label="닫기">×</button></div><p class="subtle">${p.kind==='점검'?'상태 점검 대상 · 교체 확정 아님':'정기 교체 일정 · 시연용 기준'}</p><div class="detail-grid"><div><small>현재 상태</small><b class="${a.level==='ok'?'mint':a.level==='soon'?'orange':'red'}">${a.label}</b></div><div><small>남은 거리</small><b>${remaining(a)}</b></div><div><small>마지막 관리일 / 주행거리</small><b>${a.last.date}</b><p>${num(a.last.km)} km</p></div><div><small>다음 ${p.kind} 기준</small><b>${a.nextKm===null?'거리 미설정':num(a.nextKm)+' km'}</b><p>${a.nextDate||'기간 미설정'}${Number.isFinite(a.days)?` (${a.days}일)`:''}</p></div></div><p class="stateline">예시 주기 ${p.km?num(p.km)+' km':'거리 미적용'} / ${p.months?p.months+'개월':'기간 미적용'} · 먼저 도래하는 기준</p><p class="stateline">예상 교체 비용 ${money(p.cost)} ${p.kind==='점검'?'· 점검 후 교체하는 경우의 가정':''}</p><div class="alert">${p.kind==='점검'?'거리·기간은 점검을 권장하는 참고 기준입니다. 실제 마모, 잔량, 잔여 수명을 측정하지 않습니다.':'이 기준은 제조사 인증값이 아닙니다. 차종·연식·운행 조건에 맞는 매뉴얼을 확인하세요.'}</div><div class="actions"><button id="editCriteria">기준 수정</button><button class="primary" id="recordThis">정비 기록 입력</button></div>`);$('#editCriteria').onclick=()=>criteria(id);$('#recordThis').onclick=()=>record(id)}
function criteria(id){const p=state.parts.find(p=>p.id===id);modal(`<div class="row"><h2>점검·교체 기준 수정</h2><button data-close>×</button></div><p class="subtle">${p.name} · 이 차량에만 적용되는 사용자 설정</p><form id="criteriaForm"><div class="formgrid"><label>거리 주기 (km, 0은 미적용)<input name="km" type="number" min="0" max="200000" value="${p.km}" required></label><label>기간 주기 (개월, 0은 미적용)<input name="months" type="number" min="0" max="120" value="${p.months}" required></label><label class="full">예상 교체 비용 (원)<input name="cost" type="number" min="0" max="100000000" value="${p.cost}" required></label></div><p class="error" id="modalError"></p><div class="actions"><button class="primary">기준 저장</button></div></form>`);$('#criteriaForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),km=+f.get('km'),months=+f.get('months');if(!km&&!months)return $('#modalError').textContent='거리 또는 기간 기준을 하나 이상 설정해 주세요.';Object.assign(p,{km,months,cost:+f.get('cost')});persist();$('#modal').close();render();toast('관리 기준을 저장했습니다.')}}
function record(partId='oil',recordId){const old=state.records.find(r=>r.id===recordId),r=old||{partId:partId||'oil',date:state.asOf,km:state.vehicle.odometer,cost:state.parts.find(p=>p.id===(partId||'oil')).cost,type:'교체',shop:'',note:''};modal(`<div class="row"><h2>${old?'정비 기록 수정':'새 정비 기록'}</h2><button data-close aria-label="닫기">×</button></div><form id="recordForm"><div class="formgrid"><label>소모품<select name="partId">${(old?state.parts:E.active(state)).map(p=>`<option value="${p.id}" ${r.partId===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label><label>정비 유형<select name="type"><option ${r.type==='교체'?'selected':''}>교체</option><option ${r.type==='점검'?'selected':''}>점검</option></select></label><label>정비 날짜<input name="date" type="date" value="${r.date}" max="${state.asOf}" required></label><label>정비 당시 주행거리 (km)<input name="km" type="number" min="0" max="${state.vehicle.odometer}" value="${r.km}" required></label><label>실제 교체·점검 비용 (원)<input name="cost" type="number" min="0" max="100000000" value="${r.cost}" required></label><label>정비업체 (선택)<input name="shop" maxlength="60" value="${esc(r.shop||'')}"></label><label class="full">메모 (선택)<input name="note" maxlength="200" value="${esc(r.note||'')}"></label></div><p class="subtle">정기 교체 부품의 단순 점검은 교체 일정을 초기화하지 않습니다.</p><p class="error" id="modalError"></p><div class="actions"><button type="button" data-close>취소</button><button class="primary">${old?'수정 저장':'정비 기록 저장'}</button></div></form>`);$('#recordForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),p=state.parts.find(p=>p.id===f.partId);const next={...f,id:old?.id||'r-'+Date.now(),km:+f.km,cost:+f.cost,estimate:old&&old.partId===f.partId&&old.type===f.type?old.estimate:(f.type==='교체'?p.cost:0)};try{E.saveRecord(state,next);persist();$('#modal').close();render();toast('정비 기록 저장 완료 · 다음 관리 시점이 갱신되었습니다.')}catch(err){$('#modalError').textContent=err.message}}}
function saveVehicle(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),n=+f.odometer,date=f.clock==='live'?E.iso():f.asOf;if(n<state.vehicle.odometer)return $('#formError').textContent='누적 주행거리는 현재 값보다 작을 수 없습니다.';if(state.records.some(r=>r.date>date)||state.mileage.some(r=>r.date>date))return $('#formError').textContent='기준일은 저장된 주행·정비 기록보다 이전일 수 없습니다.';state.asOf=date;state.clock=f.clock;state.vehicle={model:f.model,year:+f.year,power:f.power,odometer:n};state.warningKm=+f.warningKm;state.warningDays=+f.warningDays;setMileage(n);persist();render();toast('차량 정보를 저장했습니다.')}
function exportData(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='partsaver-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
render();if(provider.warning)toast(provider.warning);
